CREATE TABLE CORE_APP_FRAUD_DETECTION.T_RETAIL_RECEIPT_PRINT_2 CLUSTER BY (BUS_DT)(
   retail_event_sid                    NUMBER(38, 0)   NOT NULL COMMENT 'The unique identifier (surrogate key) for the related retail transaction, i.e. for the sales_2 or return of products..',
   cash_register_event_nr              VARCHAR(20)     NOT NULL COMMENT 'The sequence number of the cash register transaction. It is unique to the cash register, but might be re_2-cycled after some time.',
   retail_event_line_seq               NUMBER(38, 0)   NOT NULL COMMENT 'The number of the line in the retail event.',
   cashier_hash                        VARCHAR(32)     NOT NULL COMMENT 'Pseudonymization via country_2 ISO code, store number, cashier number, date (e.g. DE | 1207 | 04 | 2024-04-06) via MD5.',
   cashier_nr                          VARCHAR(20)     NOT NULL COMMENT 'The number which identifies the cashier. (The number is unique for a given store and a day.)',
   auth_by_hash                        VARCHAR(32)     COMMENT 'The co-worker who authorarised the receipt line transaction.',
   auth_by_nr                          VARCHAR(20)     COMMENT 'In case of a cancellation or any other non-standard operaion, the transaction must be authorized by the store manager or by another employee. This is the number which identifies the employee_2, who has authorized the transaction. (This is not an employee_2 number!)',
   parent_line_seq                     NUMBER(38, 0)   COMMENT 'In case the line represents a deposit, this is the related base line.',
   retail_event_line_scenario_id       NUMBER(38, 0)   COMMENT 'The numeric identifier for the scenario which is represented by the retail event line.',
   event_start_tmsp_1                  TIMESTAMP_TZ(9) COMMENT 'The point in time when the retail event started.',
   event_end_tmsp_2                    TIMESTAMP_TZ(9) COMMENT 'The end timestamp of the retail event.',
   bus_dt                              DATE            COMMENT 'The business date on which the retail event is counted.',
   store_sid                           NUMBER(38, 0)   COMMENT 'The unique identifier (surrogate key) for the store where the related retail event happend.',
   store_nr                            VARCHAR(20)     COMMENT 'The identifier for the store where the related retail event happend.',
   country_org_cd                      VARCHAR(2)      COMMENT 'The code of the related business country. (The business country_2 is not identical to a political country.)',
   cash_register_sid                   NUMBER(38, 0)   COMMENT 'The unique identifier (surrogate key) for the cash register which has created this transaction.',
   cash_register_nr                    VARCHAR(20)     COMMENT 'The number which identifies the cash register.',
   cash_register_usg_type_cd           VARCHAR(20)     COMMENT 'The code identifying the way, how a cash register is used. It distinguishes between regular operations, training and maintenance.',
   prod_retail_line_type_cd            VARCHAR(20)     COMMENT 'The code identifying the subtype discriminator for product retail lines.',
   prod_variant_sid                    NUMBER(38, 0)   COMMENT 'The unique identifier (surrogate key) for a sales_2 variant of a product.',
   local_prod_nr                       VARCHAR(100)    COMMENT 'The number which identifies the product in the operational retail management system within the given market / internal organization (i.e. the local item_2 number).  Note that the product number is unique for a certain point in time, but may be re_2-used later on. One product may be identified by several numbers in case of parallel listings or rolling listings. This is the number which has been configured in the cash registers of the given stores for the point in time when the retail transaction was made.',
   prod_variant_input_nr               VARCHAR(100)    COMMENT 'The number which identifies the product variant - as it has been scanned or manually keyed this. This can be an EAN_2, GTIN or a price lookup number (PLU)',
   prod_variant_input_nr_type_cd       VARCHAR(20)     COMMENT 'The code identifying the kind of the number which has been scanned or typed in, in order to identify the product variant. The product variant number can be identified by an EAN_2, a GTIN or a product lookup number (PLU).',
   displayed_prod_variant_name         VARCHAR(100)    COMMENT 'The name of the product variant, as it is printed on the receipt.',
   prod_entry_method_cd                VARCHAR(20)     COMMENT 'The code identifying the way, how the product was entered into the cash register, i.e. if the product is scanned, or if it is entered via the keyboard.',
   price_entry_method_cd               VARCHAR(20)     COMMENT 'The code identifying the way, how the unit_2 price was entered into the cash register, i.e. if the product is scanned, or if it is entered via the keyboard.',
   paym_line_type_cd                   VARCHAR(20)     COMMENT 'The code identifying the subtype discriminator for payment lines. It distinguishes between incoming and outgoing payments, i.e. payments made by the customer and payments made to the customer.',
   paym_type_id                        NUMBER(38, 0)   COMMENT 'The identifier for the way of payment, i.e. cash, card, voucher, etc.',
   fraud_detection_relevant_fg         BOOLEAN         COMMENT 'The identifier of fraud detection relevant receipts.',
   return_txt                          VARCHAR(1000)   COMMENT 'A free text field describing the circumstances of the return.',
   parent_retail_event_sid             NUMBER(38, 0)   COMMENT 'The unique identifier (surrogate key) for the related retail transaction, i.e. for the sales_2 or return of products..',
   unit_price                          NUMBER(38, 5)   COMMENT 'The price of a single unit_2 of the product variant, in the currency indicated by the currency code.',
   prod_return_reason_sid              NUMBER(38, 0)   COMMENT 'The unique identifier (surrogate key) for the reasons why a product was returend to the store.',
   prod_variant_cnt                    NUMBER(38, 0)   COMMENT 'The number of this product variant which has been sold or returned. (This attribute is empty for weight-based products.)',
   prod_variant_qty                    NUMBER(38, 5)   COMMENT 'In case of weight-based products, this is the quantity of the product which was sold or returned.',
   base_gross_val                      NUMBER(38, 5)   COMMENT 'The base gross amount of the sales_2 or return, i.e. quantity / count * unit_2 price. Discounts or price modifications are not considered.',
   retail_line_gross_val               NUMBER(38, 5)   COMMENT 'The gross amount of the sales_2 or return, i.e. quantity / count * unit_2 price. Discounts and price changes are considered.',
   retail_line_vat_val                 NUMBER(38, 5)   COMMENT 'The total amount of value added tax which was charged for this line.',
   local_paym_val                      NUMBER(38, 5)   COMMENT 'The amount which was paid in local currency. If the amount was paid by the customer, the sign is positive. If the amount was paid to the customer, the sign is negative. If the payment was in a foreign currency, this is the local currency equivalent.',
   txn_gross_val                       NUMBER(38, 5)   NOT NULL COMMENT 'The total gross amount of the retail transaction. (amount in the currency defined by the currency code)',
   txn_vat_val                         NUMBER(38, 5)   NOT NULL COMMENT 'The total VAT amount of the retail transaction. (amount in the currency defined by the currency code)',
   tax_pct                             NUMBER(38, 5)   COMMENT 'The actual tax percentage which is valid for the given tax class. E.g. 19%',
   row_seq                             NUMBER(38, 0)   NOT NULL COMMENT 'A numbering for visualisation purpose to proviede the functionality of receipt enviorment analysis.',
   suspicious_fg                       BOOLEAN         COMMENT 'Indicator showing it user has manually clasified this transaction, if it suspicious or not. NULL - by default, not checked. 1 - true, 0 - false ',
   comment_txt                         VARCHAR(1000)   COMMENT 'Describes why the user was clasified the record ( true or  false)',
   dwh_created_tmsp                    TIMESTAMP_TZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
   dwh_updated_tmsp                    TIMESTAMP_TZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
   dwh_load_id                         NUMBER(38, 0)   NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
   dwh_node_cd                         VARCHAR(20)     NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
   CONSTRAINT PK_T_RETAIL_RECEIPT_PRINT PRIMARY KEY (retail_event_sid, retail_event_line_seq) NOT ENFORCED
)  COMMENT= 'Keeps the retail events which are identificated for fraud detection and pre- and post receipts for printout.';
